revoke all on function public.rfqh4_start_revision(text) from public,anon,authenticated; grant execute on function public.rfqh4_start_revision(text) to anon,authenticated;
create or replace function rfqh_secure.rfqh4_prepare_attachment_impl(p_token_hash text,p_file_name text,p_mime_type text,p_size_bytes bigint) returns jsonb language plpgsql security definer set search_path='' as $$
declare v_dispatch public.buyer_rfq_dispatches%rowtype; v_rfq public.buyer_rfq_campaigns%rowtype; v_quote public.buyer_rfq_quotes%rowtype; v_revision int;
begin
 if p_size_bytes is null or p_size_bytes<1 or p_size_bytes>10485760 then raise exception 'Attachment must be between 1 byte and 10 MB'; end if; if p_mime_type not in('application/pdf','application/vnd.ms-excel','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet') then raise exception 'Unsupported attachment type'; end if;
 select * into v_dispatch from public.buyer_rfq_dispatches d where d.token_hash=p_token_hash and d.status not in('cancelled','failed','bounced','complained','declined') for update; if not found then raise exception 'RFQ invite is not available' using errcode='42501'; end if;
 select * into v_rfq from public.buyer_rfq_campaigns r where r.id=v_dispatch.rfq_id for update; if v_rfq.status not in('launched','collecting') then raise exception 'RFQ is not open for attachments'; end if; if v_rfq.due_at is not null and v_rfq.due_at<=now() then raise exception 'RFQ deadline has passed'; end if;
 select * into v_quote from public.buyer_rfq_quotes q where q.dispatch_id=v_dispatch.id and q.status='draft' order by q.revision_no desc limit 1 for update;
 if not found then if exists(select 1 from public.buyer_rfq_quotes q where q.dispatch_id=v_dispatch.id and q.status='submitted') then raise exception 'Start a revision before replacing a submitted attachment'; end if; select coalesce(max(q.revision_no),0)+1 into v_revision from public.buyer_rfq_quotes q where q.dispatch_id=v_dispatch.id; insert into public.buyer_rfq_quotes(rfq_id,supplier_id,dispatch_id,owner_user_id,organization_id,revision_no,status) values(v_dispatch.rfq_id,v_dispatch.supplier_id,v_dispatch.id,v_dispatch.owner_user_id,v_dispatch.organization_id,v_revision,'draft') returning * into v_quote; end if;
 if v_quote.attachment_upload_count>=5 then raise exception 'Attachment upload limit reached'; end if; return jsonb_build_object('quote_id',v_quote.id,'revision_no',v_quote.revision_no,'old_attachment_path',v_quote.attachment_path,'file_name',left(btrim(coalesce(p_file_name,'offer')),180));
end$$;
revoke all on function rfqh_secure.rfqh4_prepare_attachment_impl(text,text,text,bigint) from public,anon,authenticated; grant usage on schema rfqh_secure to service_role; grant execute on function rfqh_secure.rfqh4_prepare_attachment_impl(text,text,text,bigint) to service_role;
create or replace function public.rfqh4_prepare_attachment(p_token_hash text,p_file_name text,p_mime_type text,p_size_bytes bigint) returns jsonb language sql security invoker set search_path='' as $$select rfqh_secure.rfqh4_prepare_attachment_impl(p_token_hash,p_file_name,p_mime_type,p_size_bytes)$$;
revoke all on function public.rfqh4_prepare_attachment(text,text,text,bigint) from public,anon,authenticated; grant execute on function public.rfqh4_prepare_attachment(text,text,text,bigint) to service_role;
create or replace function rfqh_secure.rfqh4_record_attachment_impl(p_token_hash text,p_storage_path text,p_file_name text,p_mime_type text,p_size_bytes bigint) returns jsonb language plpgsql security definer set search_path='' as $$
declare v_dispatch public.buyer_rfq_dispatches%rowtype; v_quote public.buyer_rfq_quotes%rowtype;
begin
 select * into v_dispatch from public.buyer_rfq_dispatches d where d.token_hash=p_token_hash and d.status not in('cancelled','failed','bounced','complained','declined') limit 1; if not found then raise exception 'RFQ invite is not available' using errcode='42501'; end if;
 select * into v_quote from public.buyer_rfq_quotes q where q.dispatch_id=v_dispatch.id and q.status='draft' order by q.revision_no desc limit 1 for update; if not found then raise exception 'Draft quote not found'; end if;
 if p_storage_path not like(v_quote.id::text||'/v'||v_quote.revision_no::text||'/%') then raise exception 'Invalid attachment path'; end if; if p_size_bytes is null or p_size_bytes<1 or p_size_bytes>10485760 then raise exception 'Invalid attachment size'; end if; if p_mime_type not in('application/pdf','application/vnd.ms-excel','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet') then raise exception 'Unsupported attachment type'; end if; if v_quote.attachment_upload_count>=5 then raise exception 'Attachment upload limit reached'; end if;
 update public.buyer_rfq_quotes set attachment_bucket='rfq-supplier-offers',attachment_path=p_storage_path,attachment_name=left(btrim(coalesce(p_file_name,'offer')),180),attachment_mime_type=p_mime_type,attachment_size_bytes=p_size_bytes,attachment_upload_count=attachment_upload_count+1,updated_at=now() where id=v_quote.id returning * into v_quote;
 perform private.rfqh3_log_event(v_dispatch.rfq_id,v_dispatch.supplier_id,v_dispatch.owner_user_id,v_dispatch.organization_id,'quote_attachment_uploaded',jsonb_build_object('quote_id',v_quote.id,'revision_no',v_quote.revision_no,'file_name',v_quote.attachment_name,'size_bytes',p_size_bytes),null);
 return jsonb_build_object('quote_id',v_quote.id,'revision_no',v_quote.revision_no,'attachment_name',v_quote.attachment_name);
end$$;
revoke all on function rfqh_secure.rfqh4_record_attachment_impl(text,text,text,text,bigint) from public,anon,authenticated; grant execute on function rfqh_secure.rfqh4_record_attachment_impl(text,text,text,text,bigint) to service_role;
